import { InicialesPipe } from './iniciales-pipe';

describe('InicialesPipe', () => {
  const pipe = new InicialesPipe();

  it('devuelve las iniciales en mayúscula', () => {
    expect(pipe.transform('ana gómez')).toBe('AG');
  });

  it('con un solo nombre devuelve una letra', () => {
    expect(pipe.transform('Facu')).toBe('F');
  });
});

import { TestBed } from '@angular/core/testing';
import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TareasApi } from './tareas-api';

describe('TareasApi', () => {
  it('pide la lista de tareas', () => {
    TestBed.configureTestingModule({
      providers: [provideHttpClient(), provideHttpClientTesting()],
    });
    const api = TestBed.inject(TareasApi);
    const http = TestBed.inject(HttpTestingController);

    let resultado: unknown;
    api.listar().subscribe(r => (resultado = r));

    http.expectOne('/api/tareas').flush([{ id: 1, titulo: 'CI', estado: 'pendiente' }]);
    expect(resultado).toHaveLength(1);
    http.verify();   // no quedaron pedidos sin responder
  });
});

